48			{"delete 键", kvOperation{isDelete: true, key: "键"}, ""},
49			{"set", kvOperation{}, ApplyReasonUnknownCommand}, // 没有空格与键
50			{"delete", kvOperation{}, ApplyReasonUnknownCommand},
51			{"set x", kvOperation{}, ApplyReasonSetMissingEquals},     // 缺等号
52			{"set =1", kvOperation{}, ApplyReasonEmptyKey},            // 空键
53			{"set  x=1", kvOperation{}, ApplyReasonKeyHasWhitespace},  // 两个空格：键以空格开头
54			{"set x y=1", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 键含空白
55			{"set\tx=1", kvOperation{}, ApplyReasonUnknownCommand},    // 制表符不是普通空格
